INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('pg_book_roster', 'workspace', 'ws_people_ops', 'September Reading Salon Enrollment Controls', 0, '2026-08-24T09:00:00Z', '2026-08-24T09:00:00Z', '{}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_pg_book_roster', NULL, 'pg_book_roster', 'paragraph', '{"text": "Enrollment totals are released by People Operations after duplicate checks. The organizing view may show department totals; individual dietary and accessibility fields remain restricted to the assigned service contacts."}', 0, 0, 1, '2026-08-24T09:00:00Z', '2026-08-24T09:00:00Z');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('pg_feedback_policy', 'workspace', 'ws_people_ops', 'Feedback Handling Policy', 0, '2026-08-24T09:00:00Z', '2026-08-24T09:00:00Z', '{}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_pg_feedback_policy', NULL, 'pg_feedback_policy', 'paragraph', '{"text": "Raw comments and guest private details stay internal. Public sharing requires explicit approval."}', 0, 0, 2, '2026-08-24T09:00:00Z', '2026-08-24T09:00:00Z');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('pg_guest_notes', 'workspace', 'ws_people_ops', 'External Speaker Information Handling', 0, '2026-07-07T06:30:00Z', '2026-07-21T08:15:00Z', '{}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_pg_guest_notes', NULL, 'pg_guest_notes', 'paragraph', '{"text": "Public event listings may use only the name, role, session title, and image explicitly cleared by the speaker. Detailed biographies, briefing notes, travel details, and unedited audience questions stay with the organizing group."}', 0, 0, 3, '2026-07-07T06:30:00Z', '2026-07-21T08:15:00Z');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('pg_spring_salon_review', 'workspace', 'ws_people_ops', 'Spring Salon Closeout', 0, '2026-05-13T02:10:00Z', '2026-05-20T05:45:00Z', '{}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_spring_salon_review', NULL, 'pg_spring_salon_review', 'paragraph', '{"text": "The April session had 46 check-ins from 58 registrations and six books left in the learning cabinet. Two tables lacked cross-function balance, so the closeout recommends facilitator-led mixing rather than alphabetical seating."}', 0, 0, 1, '2026-05-13T02:10:00Z', '2026-05-20T05:45:00Z');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('pg_cost_center_examples', 'workspace', 'ws_people_ops', 'Event Cost Coding Examples', 0, '2026-06-30T07:00:00Z', '2026-07-14T03:20:00Z', '{}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_cost_center_examples', NULL, 'pg_cost_center_examples', 'paragraph', '{"text": "Past approvals place participant books and facilitator materials in learning programs when the business purpose is documented. Restaurant service, social refreshments, room hire, and deposits use employee-engagement or event-operations coding."}', 0, 0, 2, '2026-06-30T07:00:00Z', '2026-07-14T03:20:00Z');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('pg_access_kit', 'workspace', 'ws_people_ops', 'Portable Accessibility Kit', 0, '2026-06-23T04:00:00Z', '2026-06-25T10:30:00Z', '{}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_access_kit', NULL, 'pg_access_kit', 'paragraph', '{"text": "Asset ACCESS-KIT-04 contains two portable microphones, six large-print sign holders, cable covers, and a compact hearing loop. Ella is the named custodian; Facilities records each checkout and return."}', 0, 0, 3, '2026-06-23T04:00:00Z', '2026-06-25T10:30:00Z');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('pg_catering_controls', 'workspace', 'ws_people_ops', 'Catering Separation Closeout', 0, '2026-07-02T06:40:00Z', '2026-07-23T08:55:00Z', '{}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_catering_controls', NULL, 'pg_catering_controls', 'paragraph', '{"text": "The July corrective action closed after the caterer used sealed special meals, dedicated tongs, separate labels, and a named banquet lead. The archive stores control results without participant names or medical notes."}', 0, 0, 4, '2026-07-02T06:40:00Z', '2026-07-23T08:55:00Z');
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('pg_audio_walkthrough', 'workspace', 'ws_people_ops', 'Cloud Loft Audio Walkthrough', 0, '2026-07-24T03:25:00Z', '2026-07-24T05:10:00Z', '{}', NULL, NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_audio_walkthrough', NULL, 'pg_audio_walkthrough', 'paragraph', '{"text": "Both portable microphones reached the rear discussion tables. Corridor announcements were audible whenever the east door opened, so the facilities note recommends the west entrance during moderated sessions."}', 0, 0, 5, '2026-07-24T03:25:00Z', '2026-07-24T05:10:00Z');
